from pocket_coffea.lib.cut_functions import (
    get_HLT_cut,
    get_nObj_cut,
    get_nBtag_cut,
)

# Configuration parameters
parameters = {
    "era": "2018",
    "dataset": "semileptonic",
    "HLT_triggers": {
        "semileptonic": [
            "HLT_Mu50",
            "HLT_Ele115_CaloIdVT_GsfTrkIdT",
            "HLT_IsoMu27",
            "HLT_IsoMu30",
        ]
    },
    "jet_pT_threshold": 30,
    "n_jets_min": 4,
    "n_btags_min": 2,
}

# Skim cuts (basic filtering)
skim_cuts = {
    "HLT": get_HLT_cut(parameters["HLT_triggers"][parameters["dataset"]]),
    "Njets": get_nObj_cut(
        object_name="JetGood",
        threshold=parameters["jet_pT_threshold"],
        min_count=parameters["n_jets_min"],
    ),
}

# Preselection cuts (tighter filtering)
preselection_cuts = {
    "HLT": get_HLT_cut(parameters["HLT_triggers"][parameters["dataset"]]),
    "Njets": get_nObj_cut(
        object_name="JetGood",
        threshold=parameters["jet_pT_threshold"],
        min_count=parameters["n_jets_min"],
    ),
    "Nbtags": get_nBtag_cut(min_btags=parameters["n_btags_min"]),
}

